    qAssert(qRows('SELECT * FROM resource_requests WHERE borrower_id NOT IN ('.implode(',',array_fill(0,count($users),'?')).') ORDER BY request_id',array_values($users))===$legacyBefore,'Historical requests changed');
    echo "PASS: R6 damage/loss and partial availability E2E ({$checks} checks).\n";
}catch(Throwable $e){$failed=$e;fwrite(STDERR,'FAIL: '.$e->getMessage()."\n".$e->getTraceAsString()."\n");}
finally{
    if($pdo->inTransaction())$pdo->rollBack();
    if($users){$marks=implode(',',array_fill(0,count($users),'?'));qExec('DELETE FROM borrower_liabilities WHERE request_id IN(SELECT request_id FROM resource_requests WHERE encoded_by IN('.$marks.') OR borrower_id IN('.$marks.'))',[...array_values($users),...array_values($users)]);qExec('DELETE FROM maintenance_schedules WHERE created_by IN('.$marks.')',array_values($users));}
    $ids=$walkins;foreach($users as $uid)foreach(qRows('SELECT request_id FROM resource_requests WHERE borrower_id=?',[$uid]) as $r)$ids[]=(int)$r['request_id'];foreach(array_unique($ids) as $id){foreach(qRows('SELECT p.filename FROM return_submission_photos p JOIN return_submissions r ON r.return_id=p.return_id WHERE r.request_id=?',[$id]) as $photo)deleteReturnPhotoFile($photo['filename']);qExec('DELETE FROM request_reschedule_history WHERE request_id=?',[$id]);gsoTestDeleteLetters($pdo,$id);qExec('DELETE FROM return_submissions WHERE request_id=?',[$id]);qExec('DELETE FROM resource_requests WHERE request_id=?',[$id]);}
    foreach($users as $uid){qExec('DELETE FROM notifications WHERE user_id=?',[$uid]);qExec('DELETE FROM activity_logs WHERE user_id=?',[$uid]);}foreach($resources as $id){qExec('DELETE FROM equipment_units WHERE resource_id=?',[$id]);qExec('DELETE FROM resources WHERE resource_id=?',[$id]);}foreach($users as $id)qExec('DELETE FROM users WHERE user_id=?',[$id]);foreach($cookies as $file)@unlink($file);
}
exit($failed?1:0);
